const { app, BrowserWindow, Tray, Menu, nativeImage, ipcMain, globalShortcut } = require('electron');
const OpenAI = require('openai');
const WindowPrivacy = require('./window-privacy-simple');
let tray = null;
let mainWindow = null;

function createWindow() {
  console.log('Creating main window...');

  mainWindow = new BrowserWindow({
    width: 900,
    height: 650,
    webPreferences: {
      nodeIntegration: true,
      contextIsolation: false,
      enableRemoteModule: true,
      webSecurity: false, // Allow microphone access
      allowRunningInsecureContent: true,
      experimentalFeatures: true
    },
    // Initial settings for welcome screen (normal window)
    skipTaskbar: false, // Show in taskbar initially
    alwaysOnTop: false, // Not always on top initially
    show: false, // Don't show initially
    minimizable: true, // Allow minimize initially
    resizable: true, // Allow resizing
    transparent: false, // Not transparent initially
    frame: true, // Show window frame initially
    title: 'LightFrame',
    icon: null // We can add icon later
  });

  // Create system tray
  createTray();

  // Load the welcome screen initially
  console.log('Loading welcome.html...');
  mainWindow.loadFile('welcome.html').catch(error => {
    console.error('Failed to load welcome.html:', error);
  });

  // Handle window close - hide instead of closing
  mainWindow.on('close', (event) => {
    if (!app.isQuiting) {
      event.preventDefault();
      mainWindow.hide();
    }
  });

  // Show window after loading (since we set show: false initially)
  mainWindow.once('ready-to-show', () => {
    mainWindow.show();
    // Don't apply overlay settings yet - this is the welcome screen
  });

  return mainWindow;
}

async function applyScreenshotProtection() {
  if (!mainWindow) return;

  try {
    console.log('🔒 Applying screenshot protection...');

    // Method 1: Use the existing WindowPrivacy module for basic protection
    const basicProtectionResult = WindowPrivacy.setBasicProtection(mainWindow);
    console.log('✅ Basic protection applied:', basicProtectionResult);

    // Method 2: Advanced Windows API protection
    if (process.platform === 'win32') {
      try {
        // Get the native window handle
        const windowHandle = mainWindow.getNativeWindowHandle();
        console.log('🪟 Got native window handle, applying advanced protection...');

        // Use the WindowPrivacy module for advanced protection
        const advancedProtectionResult = await WindowPrivacy.setScreenCaptureProtection(windowHandle);
        console.log('✅ Advanced screenshot protection applied:', advancedProtectionResult);

        // Send status to renderer
        mainWindow.webContents.send('protection-status', {
          basic: basicProtectionResult,
          advanced: advancedProtectionResult,
          platform: process.platform
        });

      } catch (winError) {
        console.log('⚠️ Advanced Windows protection failed:', winError.message);
        mainWindow.webContents.send('protection-status', {
          basic: basicProtectionResult,
          advanced: false,
          platform: process.platform
        });
      }
    } else {
      // Non-Windows platforms
      mainWindow.webContents.send('protection-status', {
        basic: basicProtectionResult,
        advanced: false,
        platform: process.platform
      });
    }

    // Method 3: Block screenshot keyboard shortcuts
    mainWindow.webContents.on('before-input-event', (event, input) => {
      // Block common screenshot shortcuts
      if (input.key === 'PrintScreen' ||
        (input.control && input.shift && input.key === 'S') ||
        (input.meta && input.shift && (input.key === '3' || input.key === '4'))) {
        event.preventDefault();
        console.log('🚫 Blocked screenshot shortcut:', input.key);
      }
    });

  } catch (error) {
    console.log('❌ Screenshot protection failed:', error.message);
  }
}

function createTray() {
  // Create a simple tray icon with a basic 16x16 pixel icon
  const icon = nativeImage.createFromDataURL('data:image/png;base64,');

  try {
    tray = new Tray(icon);

    const contextMenu = Menu.buildFromTemplate([
      {
        label: 'Show App',
        click: () => {
          if (mainWindow) {
            mainWindow.show();
            mainWindow.setAlwaysOnTop(true, 'screen-saver');
          }
        }
      },
      {
        label: 'Hide App',
        click: () => {
          if (mainWindow) {
            mainWindow.hide();
          }
        }
      },
      { type: 'separator' },
      {
        label: 'Toggle Click-Through (Ctrl+Shift+T)',
        click: () => {
          if (mainWindow) {
            isClickThrough = !isClickThrough;
            mainWindow.setIgnoreMouseEvents(isClickThrough, { forward: true });
            mainWindow.webContents.send('click-through-status', isClickThrough);
            console.log('Click-through mode:', isClickThrough ? 'ON' : 'OFF');
          }
        }
      },
      {
        label: 'Toggle Always On Top',
        click: () => {
          if (mainWindow) {
            const isOnTop = mainWindow.isAlwaysOnTop();
            mainWindow.setAlwaysOnTop(!isOnTop, 'screen-saver');
          }
        }
      },
      { type: 'separator' },
      {
        label: 'Quit',
        click: () => {
          app.quit();
        }
      }
    ]);

    tray.setContextMenu(contextMenu);
    tray.setToolTip('LightFrame');
  } catch (error) {
    console.log('Tray creation failed, continuing without tray:', error.message);
  }
}


// Enable media access command line switches
app.commandLine.appendSwitch('enable-media-stream');
app.commandLine.appendSwitch('enable-usermedia-screen-capturing');
app.commandLine.appendSwitch('allow-http-screen-capture');
app.commandLine.appendSwitch('auto-select-desktop-capture-source', 'LightFrame');
app.commandLine.appendSwitch('enable-features', 'VaapiVideoDecoder');
app.commandLine.appendSwitch('ignore-certificate-errors');
app.commandLine.appendSwitch('disable-web-security');

app.whenReady().then(() => {
  console.log('Electron app is ready, creating window...');

  // Handle microphone permission requests
  const { session } = require('electron');

  // Set permission request handler
  session.defaultSession.setPermissionRequestHandler((webContents, permission, callback) => {
    console.log('Permission requested:', permission);
    if (permission === 'microphone' || permission === 'media') {
      console.log('✅ Granting microphone permission');
      callback(true);
    } else {
      console.log('❌ Denying permission:', permission);
      callback(false);
    }
  });

  // Set permission check handler
  session.defaultSession.setPermissionCheckHandler((webContents, permission, requestingOrigin, details) => {
    console.log('Permission check:', permission, requestingOrigin);
    if (permission === 'microphone' || permission === 'media') {
      console.log('✅ Allowing microphone permission check');
      return true;
    }
    return false;
  });

  // Set device permission handler
  session.defaultSession.setDevicePermissionHandler((details) => {
    console.log('Device permission requested:', details);
    if (details.deviceType === 'microphone') {
      console.log('✅ Allowing microphone device');
      return true;
    }
    return false;
  });

  createWindow();

  // Initialize AI
  initializeAI();

  // Register global shortcuts
  registerGlobalShortcuts();
}).catch(error => {
  console.error('Error during app startup:', error);
});

app.on('window-all-closed', () => {
  // Don't quit when all windows are closed - keep running in tray
  // Uncomment the line below if you want the app to quit when all windows are closed
  // if (process.platform !== 'darwin') {
  //   app.quit();
  // }
});

app.on('before-quit', () => {
  app.isQuiting = true;

  // Unregister all global shortcuts
  globalShortcut.unregisterAll();
  console.log('🧹 Global shortcuts unregistered');
});

app.on('activate', () => {
  if (BrowserWindow.getAllWindows().length === 0) {
    createWindow();
  }
});

// Track click-through state and app mode
let isClickThrough = false; // Start with click-through disabled for welcome screen
let isOverlayMode = false; // Track if we're in overlay mode

// IPC handlers for window controls
ipcMain.on('window-maximize', () => {
  if (mainWindow) {
    if (mainWindow.isMaximized()) {
      mainWindow.unmaximize();
    } else {
      mainWindow.maximize();
    }
  }
});

ipcMain.on('window-close', () => {
  if (mainWindow) {
    mainWindow.hide();
  }
});

// AI Chat Integration
let openai = null;

// Initialize OpenAI with multiple API key sources
function initializeAI() {
  try {
    // Try multiple sources for API key
    const apiKey = 
      process.env.OPENAI_API_KEY || 
      process.env.OPENAI_KEY || 
      getStoredApiKey() || 
      'your-api-key-here';
    
    if (apiKey && apiKey !== 'your-api-key-here' && apiKey.startsWith('sk-')) {
      openai = new OpenAI({
        apiKey: apiKey
      });
      console.log('✅ OpenAI initialized with API key');
      
      // Test the API key
      testApiKey();
    } else {
      console.log('⚠️ OpenAI API key not set - using mock responses');
      console.log('💡 To use real AI responses:');
      console.log('   1. Set OPENAI_API_KEY environment variable');
      console.log('   2. Or use the API key configuration in the app');
    }
  } catch (error) {
    console.error('❌ Failed to initialize OpenAI:', error);
  }
}

// Get stored API key from local storage
function getStoredApiKey() {
  try {
    const { app } = require('electron');
    const path = require('path');
    const fs = require('fs');
    
    const configPath = path.join(app.getPath('userData'), 'config.json');
    if (fs.existsSync(configPath)) {
      const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
      return config.openaiApiKey;
    }
  } catch (error) {
    console.log('No stored API key found');
  }
  return null;
}

// Store API key locally
function storeApiKey(apiKey) {
  try {
    const { app } = require('electron');
    const path = require('path');
    const fs = require('fs');
    
    const configPath = path.join(app.getPath('userData'), 'config.json');
    const config = fs.existsSync(configPath) ? 
      JSON.parse(fs.readFileSync(configPath, 'utf8')) : {};
    
    config.openaiApiKey = apiKey;
    fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
    
    console.log('✅ API key stored successfully');
    return true;
  } catch (error) {
    console.error('❌ Failed to store API key:', error);
    return false;
  }
}

// Test API key validity
async function testApiKey() {
  if (!openai) return false;
  
  try {
    await openai.chat.completions.create({
      model: 'gpt-3.5-turbo',
      messages: [{ role: 'user', content: 'Hello' }],
      max_tokens: 5
    });
    console.log('✅ API key is valid');
    return true;
  } catch (error) {
    console.error('❌ API key test failed:', error.message);
    openai = null; // Fall back to mock responses
    return false;
  }
}

// Handle AI chat requests
ipcMain.handle('chat-with-ai', async (event, message, chatHistory) => {
  try {
    console.log('💬 AI chat request:', message);
    
    if (!openai) {
      // Mock response when OpenAI is not configured
      return generateMockResponse(message);
    }
    
    // Prepare messages for OpenAI
    const messages = [
      {
        role: 'system',
        content: `You are an AI assistant integrated into LightFrame, a transparent overlay application designed to help users during interviews and meetings. You should:
        
        - Be helpful, concise, and professional
        - Provide interview tips, coding help, or general assistance
        - Keep responses brief but informative (2-4 sentences usually)
        - Be encouraging and supportive
        - Help with technical questions, interview preparation, or productivity
        - Use emojis sparingly but appropriately
        - Format code snippets with backticks when relevant
        
        The user is likely in an interview or meeting context, so be mindful of that. Provide actionable advice.`
      },
      ...chatHistory.slice(-10), // Last 10 messages for context
      { role: 'user', content: message }
    ];
    
    const completion = await openai.chat.completions.create({
      model: 'gpt-3.5-turbo',
      messages: messages,
      max_tokens: 300,
      temperature: 0.7
    });
    
    const response = completion.choices[0].message.content;
    console.log('🤖 AI response:', response);
    
    return response;
    
  } catch (error) {
    console.error('❌ AI chat error:', error);
    
    // If API key is invalid, fall back to mock responses
    if (error.message.includes('API key') || error.message.includes('authentication')) {
      openai = null;
      return generateMockResponse(message) + '\n\n⚠️ API key issue detected - switched to offline mode.';
    }
    
    return 'Sorry, I encountered an error. Please try again or check your API configuration.';
  }
});

// Handle API key configuration
ipcMain.handle('configure-api-key', async (event, apiKey) => {
  try {
    if (!apiKey || !apiKey.startsWith('sk-')) {
      return { success: false, message: 'Invalid API key format' };
    }
    
    // Test the API key first
    const testOpenAI = new OpenAI({ apiKey: apiKey });
    await testOpenAI.chat.completions.create({
      model: 'gpt-3.5-turbo',
      messages: [{ role: 'user', content: 'Hello' }],
      max_tokens: 5
    });
    
    // If test passes, store and use the key
    const stored = storeApiKey(apiKey);
    if (stored) {
      openai = testOpenAI;
      return { success: true, message: 'API key configured successfully!' };
    } else {
      return { success: false, message: 'Failed to store API key' };
    }
    
  } catch (error) {
    console.error('API key configuration error:', error);
    return { 
      success: false, 
      message: error.message.includes('API key') ? 
        'Invalid API key' : 
        'Failed to validate API key'
    };
  }
});

// Get API key status
ipcMain.handle('get-api-status', async (event) => {
  return {
    hasApiKey: !!openai,
    isConfigured: !!getStoredApiKey(),
    usingMockResponses: !openai
  };
});

function generateMockResponse(message) {
  const mockResponses = {
    'hello': '👋 Hello! I\'m your AI assistant. How can I help you today?',
    'help': '🆘 I can help with interview questions, coding problems, or general assistance. What do you need?',
    'interview': '💼 For interviews: stay calm, think out loud, ask clarifying questions, and remember - they want you to succeed!',
    'coding': '💻 For coding questions: break down the problem, consider edge cases, explain your approach, and don\'t forget to test!',
    'nervous': '😌 It\'s normal to feel nervous! Take deep breaths, remember your preparation, and focus on showing your problem-solving process.',
    'default': '🤖 I\'m here to help! You can ask me about interview tips, coding questions, or anything else you need assistance with.'
  };
  
  const lowerMessage = message.toLowerCase();
  
  for (const [key, response] of Object.entries(mockResponses)) {
    if (lowerMessage.includes(key)) {
      return response;
    }
  }
  
  return mockResponses.default;
}

// Function to register global shortcuts
function registerGlobalShortcuts() {
  console.log('🎹 Registering global shortcuts...');

  try {
    // Right Ctrl + M
    globalShortcut.register('CommandOrControl+Right+M', () => {
      console.log('🔥 Global shortcut pressed: Right Ctrl + M');
      if (mainWindow && isOverlayMode) {
        mainWindow.webContents.send('shortcut-pressed', 'Right Ctrl + M');
      }
    });

    // Right Ctrl + K for push-to-talk (we need a different approach for hold-to-listen)
    // Using a library for better key detection
    console.log('⚠️ Right Ctrl + K push-to-talk will be handled via IPC');

    // Right Ctrl + J
    globalShortcut.register('CommandOrControl+Right+J', () => {
      console.log('🔥 Global shortcut pressed: Right Ctrl + J');
      if (mainWindow && isOverlayMode) {
        mainWindow.webContents.send('shortcut-pressed', 'Right Ctrl + J');
      }
    });

    // Alternative shortcuts (in case Right modifier doesn't work)
    // Ctrl + Alt + M
    globalShortcut.register('CommandOrControl+Alt+M', () => {
      console.log('🔥 Global shortcut pressed: Ctrl + Alt + M');
      if (mainWindow && isOverlayMode) {
        mainWindow.webContents.send('shortcut-pressed', 'Ctrl + Alt + M');
      }
    });

    // Ctrl + Alt + K
    globalShortcut.register('CommandOrControl+Alt+K', () => {
      console.log('🔥 Global shortcut pressed: Ctrl + Alt + K');
      if (mainWindow && isOverlayMode) {
        mainWindow.webContents.send('shortcut-pressed', 'Ctrl + Alt + K');
      }
    });

    // Ctrl + Alt + J
    globalShortcut.register('CommandOrControl+Alt+J', () => {
      console.log('🔥 Global shortcut pressed: Ctrl + Alt + J');
      if (mainWindow && isOverlayMode) {
        mainWindow.webContents.send('shortcut-pressed', 'Ctrl + Alt + J');
      }
    });

    console.log('✅ Global shortcuts registered successfully');
    console.log('📋 Available shortcuts:');
    console.log('   - Right Ctrl + M');
    console.log('   - Right Ctrl + K');
    console.log('   - Right Ctrl + J');
    console.log('   - Ctrl + Alt + M (fallback)');
    console.log('   - Ctrl + Alt + K (fallback)');
    console.log('   - Ctrl + Alt + J (fallback)');

  } catch (error) {
    console.error('❌ Failed to register global shortcuts:', error);
  }
}

ipcMain.on('toggle-click-through', () => {
  if (mainWindow && isOverlayMode) {
    isClickThrough = !isClickThrough;
    mainWindow.setIgnoreMouseEvents(isClickThrough, { forward: true });

    // Send status back to renderer
    mainWindow.webContents.send('click-through-status', isClickThrough);

    console.log('Click-through mode:', isClickThrough ? 'ON' : 'OFF');
  }
});

ipcMain.on('start-overlay-mode', () => {
  if (mainWindow) {
    console.log('🚀 Starting overlay mode...');

    // Switch to overlay mode
    isOverlayMode = true;
    isClickThrough = true;

    // Get current window bounds
    const currentBounds = mainWindow.getBounds();
    console.log('Current window bounds:', currentBounds);

    // Create new overlay window with transparent and frameless properties
    const overlayWindow = new BrowserWindow({
      x: currentBounds.x,
      y: currentBounds.y,
      width: currentBounds.width,
      height: currentBounds.height,
      webPreferences: {
        nodeIntegration: true,
        contextIsolation: false
      },
      skipTaskbar: true,
      alwaysOnTop: true,
      show: true, // Show immediately for debugging
      minimizable: false,
      resizable: true,
      transparent: true,
      frame: false,
      title: 'LightFrame'
    });

    console.log('Created overlay window');

    // Load the overlay interface
    overlayWindow.loadFile('index.html').then(() => {
      console.log('Overlay interface loaded successfully');

      // Update the main window reference FIRST
      const oldWindow = mainWindow;
      mainWindow = overlayWindow;

      // Apply overlay settings
      overlayWindow.setAlwaysOnTop(true, 'screen-saver');
      overlayWindow.setIgnoreMouseEvents(true, { forward: true });

      console.log('✅ Overlay mode activated');

      // Apply screenshot protection to the new window
      applyScreenshotProtection();

      // Close the old welcome window after a short delay
      setTimeout(() => {
        oldWindow.destroy();
        console.log('Welcome window destroyed');
      }, 500);

    }).catch(error => {
      console.error('❌ Failed to load overlay interface:', error);
    });
  } else {
    console.error('❌ No main window found');
  }
});